package cn.dreamingfish.launcher.loaders;
import cn.dreamingfish.launcher.GameInstance.LoaderKind;
import cn.dreamingfish.launcher.downloads.*;
import cn.dreamingfish.launcher.storage.LauncherJson;
import cn.dreamingfish.launcher.vanilla.*;
import java.io.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import java.util.jar.JarFile;

/** Forge与NeoForge共享官方安装描述协议；下载、事务与进程管理仍由既有模块承担。 */
public final class ForgeProvider implements LoaderProvider {
 private final LoaderKind kind;private final VanillaPlanner vanilla;private final DownloadStore store;private final RemoteClient remote;private final Path root;
 public ForgeProvider(LoaderKind kind,VanillaPlanner vanilla,DownloadStore store,RemoteClient remote,Path root){if(kind!=LoaderKind.FORGE&&kind!=LoaderKind.NEOFORGE)throw new IllegalArgumentException("加载器类型无效");this.kind=kind;this.vanilla=vanilla;this.store=store;this.remote=remote;this.root=root.toAbsolutePath().normalize();}
 @Override public LoaderKind kind(){return kind;}
 @Override public List<LoaderVersions.Version> versions(String game,CancellationToken token)throws IOException{return new ForgeCatalog(remote).versions(kind,game,token);}
 private URI sourceUri(String game,String version){LoaderIdentity.validateVersion(game);LoaderIdentity.validateVersion(version);String artifact=kind==LoaderKind.FORGE?"forge":"neoforge",coordinateVersion=kind==LoaderKind.FORGE?game+"-"+version:version;return URI.create(ForgeCatalog.root(kind)+coordinateVersion+"/"+artifact+"-"+coordinateVersion+"-installer.jar");}
 private DownloadSpec spec(URI uri,FileDigest digest,long size){return new DownloadSpec(ForgeCatalog.service(kind),uri,size,128L*1024*1024,digest,"官方核心安装描述");}
 @Override public LoaderPlan plan(String game,String loader,CancellationToken token)throws IOException{if(versions(game,token).stream().noneMatch(v->v.version().equals(loader)))throw new TaskFailure("UNSUPPORTED_LOADER","官方未列出此游戏与核心组合");URI uri=sourceUri(game,loader);String hash=new String(remote.bytes(new RemoteRequest(ForgeCatalog.service(kind),URI.create(uri+".sha1"),Map.of()),256,token),StandardCharsets.US_ASCII).strip();var object=store.fetch(spec(uri,new FileDigest(FileDigest.Algorithm.SHA1,hash),-1),token,n->{});return build(vanilla.plan(game,token),loader,object,uri,token);}
 @Override public LoaderPlan pinned(String game,String metadataSha1,String loader,String sourceSha256,String fingerprint,CancellationToken token)throws IOException{URI uri=sourceUri(game,loader);var object=store.fetch(spec(uri,new FileDigest(FileDigest.Algorithm.SHA256,sourceSha256),-1),token,n->{});return build(vanilla.planPinned(game,metadataSha1,token),loader,object,uri,token).requireFingerprint(fingerprint);}
 private LoaderPlan build(VanillaPlan base,String loader,VerifiedDownload object,URI uri,CancellationToken token)throws IOException{var identity=new LoaderIdentity(kind,loader);var profile=ForgeInstallerProfile.read(root.resolve(object.relativeObject()),identity,base.versionId());var files=new LinkedHashMap<Path,InstallFile>();for(var file:base.files())files.put(file.relativePath(),file);LoaderFiles.add(files,new InstallFile(Path.of("versions/installer.jar"),spec(uri,new FileDigest(FileDigest.Algorithm.SHA256,object.sha256()),object.size())));var resolver=new LoaderFiles(store,remote);for(var lib:profile.libraries()){token.check();if(lib.uri()==null)throw new TaskFailure("UNSUPPORTED_LOADER_FORMAT","安装工具缺少官方文件来源");LoaderFiles.add(files,resolver.resolve(lib,token));}for(var lib:profile.client().libraries()){token.check();if(lib.uri()!=null)LoaderFiles.add(files,resolver.resolve(lib,token));}
  if(profile.processors().stream().anyMatch(p->p.args().contains("DOWNLOAD_MOJMAPS"))){var metadata=base.files().stream().filter(f->f.relativePath().toString().replace('\\','/').equals("versions/game.json")).findFirst().orElseThrow();var data=LauncherJson.read(store.read(store.fetch(metadata.download(),token,n->{}),4*1024*1024,token),4*1024*1024).path("downloads").path("client_mappings");if(!data.path("size").isIntegralNumber()||!data.path("size").canConvertToLong())throw new TaskFailure("UNSUPPORTED_LOADER_FORMAT","官方版本缺少客户端映射");LoaderFiles.add(files,new InstallFile(Path.of("versions/client-mappings.txt"),new DownloadSpec(RemoteService.MOJANG_FILES,URI.create(LauncherJson.text(data,"url",4096)),data.path("size").longValue(),64L*1024*1024,new FileDigest(FileDigest.Algorithm.SHA1,LauncherJson.text(data,"sha1",40)),"官方客户端映射")));}
  return LoaderPlan.fixed(new VanillaPlan(base.versionId(),base.metadataSha1(),base.platform(),base.requiredJavaMajor(),new ArrayList<>(files.values()),0,null,identity),object.sha256());
 }
 @Override public InstallationReceipt install(String instanceId,LoaderPlan plan,VanillaInstaller installer,TaskContext context)throws IOException{return installer.install(instanceId,plan.installation(),context,(stage,token)->generate(stage,plan.installation(),token));}
 private List<Path> generate(Path stage,VanillaPlan plan,CancellationToken token)throws IOException{
  var profile=ForgeInstallerProfile.read(stage.resolve("versions/installer.jar"),plan.component(),plan.versionId());var downloaded=new HashSet<Path>();for(var f:plan.files())downloaded.add(f.relativePath());Files.write(stage.resolve(plan.component().profilePath()),profile.versionJson(),StandardOpenOption.CREATE_NEW);for(var entry:profile.embedded().entrySet()){Path file=stage.resolve("versions/installer-data").resolve(SafeInstallPath.parse(entry.getKey()));Files.createDirectories(file.getParent());Files.write(file,entry.getValue(),StandardOpenOption.CREATE_NEW);}
  var values=new HashMap<String,String>();values.put("ROOT",stage.toString());values.put("SIDE","client");values.put("INSTALLER",stage.resolve("versions/installer.jar").toString());values.put("MINECRAFT_JAR",stage.resolve("versions/client.jar").toString());values.put("LIBRARY_DIR",stage.resolve("libraries").toString());for(var e:profile.data().entrySet()){String value=e.getValue();if(value.startsWith("["))value=library(stage,ForgeInstallerProfile.coordinate(value)).toString();else if(value.startsWith("/"))value=stage.resolve("versions/installer-data").resolve(value.substring(1)).toString();else value=value.substring(1,value.length()-1);values.put(e.getKey(),value);}
  // ForgeBootstrap读取原始客户端坐标；复制到该安装的独立libraries，原客户端保持只读。
  if(profile.data().containsKey("MC_UNPACKED")&&profile.data().get("MC_UNPACKED").startsWith("[")){Path file=Path.of(values.get("MC_UNPACKED"));Files.createDirectories(file.getParent());if(!Files.exists(file))Files.copy(stage.resolve("versions/client.jar"),file);}
  var executor=new ProcessorExecutor();for(var processor:profile.processors()){token.check();var jars=new LinkedHashSet<Path>();jars.add(library(stage,MavenLibrary.path(processor.jar())));for(String cp:processor.classpath())jars.add(library(stage,MavenLibrary.path(cp)));for(Path jar:jars)if(!downloaded.contains(stage.relativize(jar)))throw new TaskFailure("UNSUPPORTED_LOADER_FORMAT","处理器依赖未固定在计划中");var args=new ArrayList<String>();for(String arg:processor.args())args.add(resolve(arg,values,stage));if(processor.args().contains("DOWNLOAD_MOJMAPS")){int output=args.indexOf("--output");if(output<0||output+1>=args.size()||!processor.args().contains("--version")||!args.get(args.indexOf("--version")+1).equals(plan.versionId()))throw new TaskFailure("UNSUPPORTED_LOADER_FORMAT","映射任务参数无效");Path target=inside(stage,Path.of(args.get(output+1)));Files.createDirectories(target.getParent());Path input=stage.resolve("versions/client-mappings.txt");if(args.contains("--sanitize"))executor.run(stage,new ArrayList<>(jars),"sqy.mapping.Sanitize",List.of(input.toString(),target.toString()),token,Duration.ofMinutes(2));else Files.copy(input,target,StandardCopyOption.REPLACE_EXISTING);}
   else{if(processor.jar().contains(":ForgeAutoRenamingTool:")||processor.jar().contains(":AutoRenamingTool:")){if(args.contains("--threads"))throw new TaskFailure("UNSUPPORTED_LOADER_FORMAT","来源不应覆盖本机处理线程数");args.add("--threads");args.add("1");}String main;try(var jar=new JarFile(jars.iterator().next().toFile())){main=jar.getManifest().getMainAttributes().getValue("Main-Class");}executor.run(stage,new ArrayList<>(jars),main,args,token,Duration.ofMinutes(5));}
   for(var output:processor.outputs().entrySet()){Path file=inside(stage,Path.of(resolve(output.getKey(),values,stage)));String hash=resolve(output.getValue(),values,stage);if(!hash.matches("[0-9a-fA-F]{1,40}"))throw new TaskFailure("UNSUPPORTED_LOADER_FORMAT","处理器输出摘要格式无效");verify(file,new FileDigest(FileDigest.Algorithm.SHA1,"0".repeat(40-hash.length())+hash),null,token);}
  }
  if(!values.containsKey("PATCHED")||!Files.isRegularFile(Path.of(values.get("PATCHED"))))throw new TaskFailure("PROCESSOR_FAILED","核心未生成客户端文件");for(var lib:profile.client().libraries())verify(library(stage,lib.path()),lib.digest(),lib.size(),token);
  var result=new ArrayList<Path>();try(var paths=Files.walk(stage)){for(Path file:paths.filter(Files::isRegularFile).toList()){token.check();Path relative=stage.relativize(file);if(!downloaded.contains(relative)&&!relative.startsWith(Path.of("versions/processor-work"))){if(!relative.startsWith("versions")&&!relative.startsWith("libraries"))throw new IOException("核心生成文件超出安装区域");result.add(relative);}}}return List.copyOf(result);
 }
 private static Path library(Path stage,String relative)throws IOException{return inside(stage,stage.resolve("libraries").resolve(SafeInstallPath.parse(relative)));}
 private static Path inside(Path stage,Path file)throws IOException{Path path=file.toAbsolutePath().normalize();if(!path.startsWith(stage)||Files.isSymbolicLink(path))throw new IOException("核心处理路径越界");return path;}
 private static String resolve(String text,Map<String,String> values,Path stage)throws IOException{if(text.startsWith("["))return library(stage,ForgeInstallerProfile.coordinate(text)).toString();String result=text;for(var entry:values.entrySet())result=result.replace("{"+entry.getKey()+"}",entry.getValue());if(result.contains("{")||result.contains("}"))throw new TaskFailure("UNSUPPORTED_LOADER_FORMAT","未知核心处理变量");return result;}
 static void verify(Path file,FileDigest expected,Long size,CancellationToken token)throws IOException{if(!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>2L*1024*1024*1024||size!=null&&Files.size(file)!=size)throw new TaskFailure("PROCESSOR_FAILED","核心输出缺失或长度不符");var digest=expected.newDigest();try(var in=Files.newInputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){token.check();digest.update(b,0,n);}}if(!HexFormat.of().formatHex(digest.digest()).equals(expected.hex()))throw new TaskFailure("PROCESSOR_FAILED","核心输出摘要不符");}
}
